/* Reset box-sizing for all elements */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: #f5f5f5;
  font-family: cursive;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100vh;
}

/* Canvas styling */
canvas {
  border: 2px solid steelblue;
  cursor: crosshair;
}

/* Toolbar container */
.toolbox {
  background-color: steelblue;
  border: 1px solid slateblue;
  display: flex;
  width: 804px;
  padding: 1rem;
  margin-top: 10px;
}

/* Toolbar buttons and input */
.toolbox * {
  background-color: #fff;
  border: none;
  font-size: 2rem;
  height: 50px;
  width: 50px;
  margin: 0.25rem;
  padding: 0.25rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.3s ease;
}

.toolbox *:hover {
  background-color: #ddd;
}

.toolbox #clear {
  margin-left: auto;
}

